def f(g):
    h=len(g); w=len(g[0]); n=w//2
    A=[r[:n] for r in g]; B=[r[n:] for r in g]
    return [[4 if A[i][j]==0 and B[i][j]==0 else 0 for j in range(n)] for i in range(h)]
